{"command": "cd /work && python3 - <<'EOF'
import json, csv

cfg = json.load(open('config.json'))
threshold = cfg['threshold']
mode = cfg['mode']
print("config OK:", cfg)

rows = list(csv.DictReader(open('data.csv', newline='')))
if mode == 'gt':
    kept = [r for r in rows if float(r['amount']) > threshold]
elif mode == 'lt':
    kept = [r for r in rows if float(r['amount']) < threshold]
elif mode == 'ge':
    kept = [r for r in rows if float(r['amount']) >= threshold]
elif mode == 'le':
    kept = [r for r in rows if float(r['amount']) <= threshold]
else:
    raise SystemExit(f"unsupported mode: {mode}")

with open('result.md', 'w') as f:
    for r in kept:
        f.write(r['id'] + '\n')

print("kept:", [r['id'] for r in kept])
EOF", "description": "Parse fixed config and filter data"}
